func TestValidateIPAgainstList(t *testing.T) {
	list := "bad CIDR, 192.0.2.0/24, 2001:db8::/32, @"
	for _, address := range []string{"192.0.2.1:4533", "[2001:db8::1]:4533", "@"} {
		if !validateIPAgainstList(address, list) {
			t.Errorf("expected %q to match", address)
		}
	}
	for _, address := range []string{"192.0.3.1:4533", "[2001:db9::1]:4533", "@"} {
		checkList := list
		if address == "@" {
			checkList = "192.0.2.0/24"
		}
		if validateIPAgainstList(address, checkList) {
			t.Errorf("expected %q not to match", address)
		}
	}
	if validateIPAgainstList("192.0.2.1:4533", "") {
		t.Fatal("empty whitelist must disable proxy authentication")
	}
}

func TestHandleLoginFromHeaders(t *testing.T) {
	previous := *conf.Server
	defer func() { *conf.Server = previous }()
	conf.Server.ReverseProxyWhitelist = "192.0.2.0/24"
	conf.Server.ReverseProxyUserHeader = "Remote-User"
	ds := &tests.MockDataStore{}
	r := httptest.NewRequest("GET", "/app/", nil)
	r.RemoteAddr = "203.0.113.1:5555"
	r.Header.Set("Remote-User", "alice")
	if got := handleLoginFromHeaders(ds, r); got != nil {
		t.Fatal("untrusted peer received auth data")
	}
	r = r.WithContext(request.WithPeerAddress(r.Context(), "192.0.2.1:5555"))
	payload := handleLoginFromHeaders(ds, r)
	if payload == nil || payload["username"] != "alice" || payload["isAdmin"] != true {
		t.Fatalf("unexpected first login payload: %v", payload)
	}
	for _, key := range []string{"id", "name", "token", "subsonicSalt", "subsonicToken"} {
		if payload[key] == "" || payload[key] == nil {
			t.Errorf("missing %s", key)
		}
	}
	if _, err := auth.Validate(payload["token"].(string)); err != nil {
		t.Fatalf("invalid token: %v", err)
	}
	user, err := ds.User(context.Background()).FindByUsername("alice")
	if err != nil || !user.IsAdmin {
		t.Fatalf("user was not created: %v", err)
	}
	if handleLoginFromHeaders(ds, r) == nil {
		t.Fatal("existing user should authenticate")
	}
}

func TestServeIndexProxyAuth(t *testing.T) {
	previous := *conf.Server
	defer func() { *conf.Server = previous }()
	conf.Server.ReverseProxyWhitelist = "192.0.2.0/24"
	conf.Server.ReverseProxyUserHeader = "Remote-User"
	ds := &tests.MockDataStore{}
	index := serveIndex(ds, os.DirFS("tests/fixtures"))
	r := httptest.NewRequest("GET", "/app/", nil)
	r.Header.Set("Remote-User", "alice")
	r.RemoteAddr = "203.0.113.1:5000"
	w := httptest.NewRecorder()
	index(w, r)
	if _, ok := extractAppConfig(w.Body.String())["auth"]; ok {
		t.Fatal("untrusted request exposed auth")
	}
	r = r.WithContext(request.WithPeerAddress(r.Context(), "192.0.2.1:5000"))
	w = httptest.NewRecorder()
	index(w, r)
	if _, ok := extractAppConfig(w.Body.String())["auth"]; !ok {
		t.Fatal("trusted request missing auth")
	}
	r.Header.Del("Remote-User")
	w = httptest.NewRecorder()
	index(w, r)
	if _, ok := extractAppConfig(w.Body.String())["auth"]; ok {
		t.Fatal("missing username exposed auth")
	}
}

import jwtDecode from 'jwt-decode'
import md5 from 'blueimp-md5'
import { v4 as uuidv4 } from 'uuid'
import { baseUrl } from './utils'
import config from './config'
import { startEventStream, stopEventStream } from './eventStream'

const authProvider = {
  login: ({ username, password }) => {
    let url = baseUrl('/app/login')
    if (config.firstTime) {
      url = baseUrl('/app/createAdmin')
    }
    const request = new Request(url, {
      method: 'POST',
      body: JSON.stringify({ username, password }),
      headers: new Headers({ 'Content-Type': 'application/json' }),
    })
    return fetch(request)
      .then((response) => {
        if (response.status < 200 || response.status >= 300) {
          throw new Error(response.statusText)
        }
        return response.json()
      })
      .then((response) => {
        // Validate token
        jwtDecode(response.token)
        // TODO Store all items in one object
        localStorage.setItem('token', response.token)
        localStorage.setItem('userId', response.id)
        localStorage.setItem('name', response.name)
        localStorage.setItem('username', response.username)
        response.avatar && localStorage.setItem('avatar', response.avatar)
        localStorage.setItem('role', response.isAdmin ? 'admin' : 'regular')
        const salt = generateSubsonicSalt()
        localStorage.setItem('subsonic-salt', salt)
        localStorage.setItem(
          'subsonic-token',
          generateSubsonicToken(password, salt)
        )
        // Avoid going to create admin dialog after logout/login without a refresh
        config.firstTime = false
        if (config.devActivityPanel) {
          startEventStream()
        }
        return response
      })
      .catch((error) => {
        if (
          error.message === 'Failed to fetch' ||
          error.stack === 'TypeError: Failed to fetch'
        ) {
          throw new Error('errors.network_error')
        }

        throw new Error(error)
      })
  },

  logout: () => {
    stopEventStream()
    removeItems()
    try {
      clearServiceWorkerCache()
    } catch (e) {
      console.log('Error clearing service worker cache:', e)
    }
    return Promise.resolve()
  },

  checkAuth: () =>
    localStorage.getItem('token') ? Promise.resolve() : Promise.reject(),

  checkError: ({ status }) => {
    if (status === 401) {
      removeItems()
      return Promise.reject()
    }
    return Promise.resolve()
  },

  getPermissions: () => {
    const role = localStorage.getItem('role')
    return role ? Promise.resolve(role) : Promise.reject()
  },

  getIdentity: () => {
    return {
      id: localStorage.getItem('username'),
      fullName: localStorage.getItem('name'),
      avatar: localStorage.getItem('avatar'),
    }
  },
}

if (config.auth) {
  const auth = config.auth
  jwtDecode(auth.token)
  localStorage.setItem('token', auth.token)
  localStorage.setItem('userId', auth.id)
  localStorage.setItem('name', auth.name)
  localStorage.setItem('username', auth.username)
  if (auth.avatar) localStorage.setItem('avatar', auth.avatar)
  localStorage.setItem('role', auth.isAdmin ? 'admin' : 'regular')
  localStorage.setItem('subsonic-salt', auth.subsonicSalt)
  localStorage.setItem('subsonic-token', auth.subsonicToken)
  config.firstTime = false
}

const removeItems = () => {
  localStorage.removeItem('token')
  localStorage.removeItem('userId')
  localStorage.removeItem('name')
  localStorage.removeItem('username')
  localStorage.removeItem('avatar')
  localStorage.removeItem('role')
  localStorage.removeItem('subsonic-salt')
  localStorage.removeItem('subsonic-token')
}

const clearServiceWorkerCache = () => {
  window.caches &&
    caches.keys().then(function (keyList) {
      for (let key of keyList) caches.delete(key)
    })
}

const generateSubsonicSalt = () => {
  const h = md5(uuidv4())
  return h.slice(0, 6)
}

const generateSubsonicToken = (password, salt) => {
  return md5(password + salt)
}

